import {STAGES,STORAGE_KEY,localDay,dayOffset,isOverdue,saveOrder,filterOrders,trackOrder,csvCell,summary,validState} from './model.js';
import {dictionaries,locale} from './i18n.js';

const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',monitor:'M3 4h18v13H3zM8 21h8M12 17v4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',user:'M20 21v-2a7 7 0 0 0-14 0v2',wrench:'M14.7 6.3a5.5 5.5 0 0 0-7 7L3 18a2.1 2.1 0 0 0 3 3l4.7-4.7a5.5 5.5 0 0 0 7-7l-3 3-3-3 3-3Z',scan:'M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5M8 12h8',chart:'M4 3v18h17M9 16v-5M14 16V7M19 16v-8',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',up:'M7 17 17 7M7 7h10v10',chevron:'m9 5 7 7-7 7',search:'m21 21-5-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2',download:'M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4',upload:'M12 16V4m-5 5 5-5 5 5M5 17v4h14v-4',printer:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',reset:'M3 10a9 9 0 1 1 2 8M3 4v6h6',info:'M12 11v6M12 7v.01',copy:'M9 9h12v12H9zM5 15H3V3h12v2',calendar:'M3 5h18v16H3zM7 3v4M17 3v4M3 10h18',folder:'M3 5h7l2 3h9v13H3z',play:'m9 5 11 7-11 7V5Z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z',settings:'M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1M5.6 18.4l2.1-2.1m8.6-8.6 2.1-2.1'};
function icon(name,size=20){const circle=['clock','info','settings'].includes(name)?'<circle cx="12" cy="12" r="9"/>':name==='search'?'<circle cx="10.5" cy="10.5" r="7.5"/>':name==='users'?'<circle cx="9" cy="7" r="4"/>':name==='user'?'<circle cx="13" cy="7" r="4"/>':'';return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${circle}<path d="${paths[name]||paths.monitor}"/></svg>`;}
let state={version:1,customers:[],technicians:[],orders:[]},lang='ru',loadMessage='';
try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const s=JSON.parse(raw);if(validState(s))state=s;else loadMessage='storageCorrupt';}const l=localStorage.getItem('tm-demo-language');if(dictionaries[l])lang=l;}catch{loadMessage='storageError';}
let page='dashboard',query='',status='',onlyOverdue=false,from='',to='',tracking=null,trackingInput={id:'',token:''},pendingImport=null,toastTimer,dialogReturn=null;
const t=k=>dictionaries[lang][k]||k;
const money=n=>new Intl.NumberFormat(locale[lang],{maximumFractionDigits:2}).format(n)+' TMT';
const date=s=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString(locale[lang],{day:'numeric',month:'short'}):'—';
const fullDate=s=>new Date(s).toLocaleString(locale[lang],{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const person=(id,kind='customers')=>state[kind].find(p=>p.id===id);
const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase();
const avatar=(p,large=false)=>`<span class="avatar ${large?'large':''}">${esc(initials(p?.name||'—'))}</span>`;
const badge=s=>`<span class="badge ${esc(s)}"><i></i>${t(s)}</span>`;
const btn=(action,text,ic='plus',cls='primary',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${ic?icon(ic,17):''}<span>${text}</span></button>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function persist(next){state=next;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast(t('storageError'));return false;}}
const navItems=[['dashboard','grid'],['orders','monitor'],['customers','users'],['technicians','wrench'],['portal','scan'],['reports','chart']];
function render(){
  document.documentElement.lang=lang;
  $('#app').innerHTML=`<button class="menu-scrim" data-action="close-menu" aria-label="${t('close')}"></button><aside class="sidebar"><a href="#dashboard" class="brand" aria-label="TehnoMerkez"><span class="brand-mark">${icon('monitor',24)}</span><span>Tehno<span class="brand-light">Merkez</span><small>${t('subtitle')}</small></span></a><div class="workspace-caption">${t('workspace')}</div><nav aria-label="${t('nav')}">${navItems.map(([p,i])=>`<a href="#${p}" class="nav-item ${page===p?'selected':''}" ${page===p?'aria-current="page"':''}>${icon(i,19)}<span>${t(p)}</span>${p==='orders'?`<b>${state.orders.length}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><button data-action="settings" class="data-button">${icon('settings',18)}<span>${t('settings')}</span></button><div class="workspace-identity"><span class="avatar">TM</span><div><strong>TehnoMerkez</strong><small><i></i>${t('local')}</small></div><span class="version-tag">01</span></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="${t('menu')}">${icon('menu')}</button><span>TehnoMerkez</span>${icon('chevron',12)}<b>${t(page)}</b></div><div class="top-tools"><span class="top-date">${icon('calendar',15)}${new Date().toLocaleDateString(locale[lang],{day:'numeric',month:'long',year:'numeric'})}</span><select id="language" aria-label="${t('language')}"><option value="ru" ${lang==='ru'?'selected':''}>RU</option><option value="tk" ${lang==='tk'?'selected':''}>TM</option><option value="en" ${lang==='en'?'selected':''}>EN</option></select><button class="icon-button bell" data-action="notifications" aria-label="${t('notification')}">${icon('bell')}${summary(state.orders).overdue?'<i></i>':''}</button><span class="avatar top-avatar">TM</span></div></header><main id="main">${renderPage()}</main><footer><span><i></i>${t('storageNote')}</span><span>${t('version')}</span></footer></div>`;
}
function heading(title,sub,action='',eyebrow='TEHNOMERKEZ / '+t(page).toUpperCase()){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function empty(text=t('emptyHelp')){return `<div class="empty"><span>${icon('search',28)}</span><h3>${t('empty')}</h3><p>${text}</p>${btn('clear',t('clearFilters'),'reset','secondary')}</div>`;}
function stats(orders,report=false){const s=summary(orders);const items=report?[[orders.length,'reportCount','folder',''],[s.active,'active','wrench','activeCaption'],[s.completed,'completed','check','completedCaption'],[money(s.total),'total','chart','totalCaption']]:[[s.active,'active','monitor','activeCaption'],[s.ready,'ready','check','readyCaption'],[s.completed,'completed','folder','completedCaption'],[money(s.total),'total','chart','totalCaption']];return `<section class="metrics" aria-label="${t('results')}">${items.map(([value,key,ic,caption],i)=>`<article class="metric metric-${i}"><div class="metric-top"><span>${t(key)}</span><span class="metric-icon">${icon(ic,18)}</span></div><strong>${value}</strong><small>${t(caption)}</small><span class="metric-line"></span></article>`).join('')}</section>`;}
function table(list){return `<div class="table-wrap"><table><thead><tr>${['orderId','device','customer','status','technician','deadline'].map(k=>`<th scope="col">${t(k)}</th>`).join('')}<th><span class="sr-only">${t('actions')}</span></th></tr></thead><tbody>${list.map(o=>`<tr><td><button class="order-link" data-action="detail" data-id="${esc(o.id)}">${esc(o.id)}</button><small>${date(o.created)}</small></td><td><div class="device-cell"><span class="device-icon">${icon('monitor',19)}</span><div><strong>${esc(o.device)}</strong><small>${esc(o.problem)}</small></div></div></td><td>${esc(person(o.customer)?.name)}</td><td>${badge(o.status)}${o.priority==='urgent'?`<small class="urgent-text">${t('urgent')}</small>`:''}</td><td><span class="table-person">${avatar(person(o.technician,'technicians'))}<span>${esc(person(o.technician,'technicians')?.name.split(' ')[0]||t('unassigned'))}</span></span></td><td class="${isOverdue(o)?'overdue-date':''}">${date(o.deadline)}${isOverdue(o)?`<small>${t('overdue')}</small>`:''}</td><td><button class="icon-button" data-action="detail" data-id="${esc(o.id)}" aria-label="${t('open')} ${esc(o.id)}">${icon('chevron',16)}</button></td></tr>`).join('')}</tbody></table>${!list.length?empty():''}</div>`;}
function laptop(){return `<div class="laptop-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-plus a">+</span><span class="art-plus b">+</span><div class="laptop-screen"><div class="screen-brand">tm<span>_</span></div><div class="screen-line"><i></i><i></i><i></i><i></i></div></div><div class="laptop-base"></div></div>`;}
function dashboard(){const s=summary(state.orders),focus=state.orders.find(o=>o.status==='repair')||state.orders.find(o=>!['completed','ready'].includes(o.status));return heading(t('welcome'),t('intro'),btn('new-order',t('newOrder')),t('eyebrow'))+stats(state.orders)+`<div class="overview-grid"><section class="panel workflow-panel"><div class="section-heading"><div><h2>${t('flow')}</h2><p>${t('flowSub')}</p></div><span class="section-number">01—05</span></div><div class="pipeline">${STAGES.map((s,i)=>`<button class="stage-item ${s}" data-action="stage-filter" data-status="${s}"><span class="stage-top"><span class="stage-symbol">${icon(['folder','search','wrench','check','shield'][i],20)}</span><b>${state.orders.filter(o=>o.status===s).length}</b></span><strong>${t(s)}</strong><span class="stage-foot">0${i+1}<span>→</span></span></button>`).join('')}</div>${s.overdue?`<button class="attention" data-action="overdue"><span class="attention-icon">${icon('clock',18)}</span><span><strong>${t('needsAttention')} <b>${s.overdue}</b></strong><small>${t('attentionHelp')}</small></span>${icon('arrow',20)}</button>`:`<div class="all-good">${icon('check',19)}${t('noAlerts')}</div>`}</section><section class="focus-card"><div class="focus-heading"><span>${t('focus')}</span><span class="pulse-dot"></span></div>${laptop()}<div class="focus-copy"><small>${focus?esc(focus.id):'TEHNOMERKEZ'}</small><h2>${focus?esc(focus.device):t('noActive')}</h2>${focus?`<div class="focus-bottom">${badge(focus.status)}<button class="round-arrow" data-action="detail" data-id="${esc(focus.id)}" aria-label="${t('openOrder')}">${icon('up',20)}</button></div>`:btn('new-order',t('newOrder'),'plus','light')}</div></section></div><section class="panel recent-panel"><div class="section-heading"><div><h2>${t('recent')}</h2><p>${t('recentSub')}</p></div><a href="#orders" class="text-link">${t('allOrders')}${icon('arrow',16)}</a></div>${table(filterOrders(state).slice(0,5))}</section><div class="bottom-grid"><section class="panel"><div class="section-heading"><h2>${t('volume')}</h2><span class="muted-label">${t('count')}</span></div>${chart()}</section><section class="panel"><div class="section-heading"><div><h2>${t('workload')}</h2><p>${t('workloadSub')}</p></div><a href="#technicians" class="icon-button" aria-label="${t('team')}">${icon('up',18)}</a></div><div class="team-list">${state.technicians.map(p=>{const n=state.orders.filter(o=>o.technician===p.id&&!['completed','ready'].includes(o.status)).length;return `<button class="team-row" data-action="edit-person" data-kind="technicians" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.specialty)}</small></span><div class="load-bar"><i style="width:${Math.min(n/5,1)*100}%"></i></div><b>${n}</b></button>`;}).join('')||`<p>${t('teamEmpty')}</p>`}</div></section></div>`;}
function chart(){const days=Array.from({length:7},(_,i)=>{const day=dayOffset(i-6);return {day,n:state.orders.filter(o=>o.created.slice(0,10)===day).length};});const max=Math.max(1,...days.map(d=>d.n));return `<div class="bar-chart">${days.map(({day,n},i)=>`<div class="bar-column"><span>${n}</span><div class="bar-track"><div class="bar ${i===6?'today':''}" style="height:${Math.max(2,n/max*100)}%"></div></div><small>${date(day)}</small></div>`).join('')}</div>`;}
function ordersPage(){const list=filterOrders(state,{query,status,overdue:onlyOverdue});return heading(t('orders'),t('recentSub'),btn('new-order',t('newOrder')))+`<section class="panel"><div class="toolbar"><label class="search-box">${icon('search',18)}<input id="search" value="${esc(query)}" placeholder="${t('search')}" aria-label="${t('search')}"></label><select id="status-filter" aria-label="${t('status')}"><option value="">${t('all')}</option>${STAGES.map(s=>`<option value="${s}" ${s===status?'selected':''}>${t(s)}</option>`).join('')}</select><span class="result-count">${list.length} ${t('count')}</span></div>${onlyOverdue?`<div class="filter-indicator">${t('overdue')}${btn('clear',t('clearFilters'),'close','subtle')}</div>`:''}${table(list)}</section>`;}
function peoplePage(kind){const isTech=kind==='technicians',list=state[kind].filter(p=>[p.name,p.phone,p.email,p.specialty].join(' ').toLowerCase().includes(query.toLowerCase()));return heading(t(kind),isTech?t('workloadSub'):t('customersIntro'),btn(isTech?'new-technician':'new-customer',t(isTech?'newTechnician':'newCustomer')))+`<div class="people-toolbar"><label class="search-box">${icon('search',18)}<input id="search" value="${esc(query)}" placeholder="${t('searchPeople')}" aria-label="${t('searchPeople')}"></label><span>${list.length} ${t('people')}</span></div><div class="people-grid">${list.map(p=>{const orders=filterOrders(state).filter(o=>o[isTech?'technician':'customer']===p.id);return `<article class="panel person-card"><div class="person-top">${avatar(p,true)}<button class="icon-button" data-action="edit-person" data-id="${esc(p.id)}" data-kind="${kind}" aria-label="${t('personEdit')} ${esc(p.name)}">${icon('up',19)}</button></div><h2>${esc(p.name)}</h2><p class="person-role">${esc(p.specialty||t('customer'))}</p><div class="person-contact"><span>${esc(p.phone)}</span><span>${esc(p.email||'—')}</span></div><div class="person-count"><span>${t(isTech?'active':'orders')}</span><b>${isTech?orders.filter(o=>!['ready','completed'].includes(o.status)).length:orders.length}</b></div><div class="person-orders">${orders.slice(0,3).map(o=>`<button data-action="detail" data-id="${esc(o.id)}"><span>${esc(o.device)}</span><i class="status-dot ${o.status}" title="${t(o.status)}"></i>${icon('chevron',12)}</button>`).join('')||`<small>${t('noPersonOrders')}</small>`}</div></article>`;}).join('')}</div>${!list.length?empty():''}`;}
function portalPage(){return heading(t('trackingTitle'),t('trackingIntro'),'','TEHNOMERKEZ / '+t('portal').toUpperCase())+`<div class="tracking-layout"><section class="panel tracking-form"><span class="tracking-icon">${icon('scan',32)}</span><h2>${t('portal')}</h2><p>${t('trackingHint')}</p><form id="tracking-form"><label>${t('orderId')}<input name="id" required maxlength="40" placeholder="TM-1041" value="${esc(trackingInput.id)}" autocomplete="off"></label><label>${t('trackingCode')}<input name="token" required maxlength="40" placeholder="${t('trackingCode')}" value="${esc(trackingInput.token)}" autocomplete="off"></label><button class="button primary" type="submit">${t('findRepair')}${icon('arrow',17)}</button></form><small class="tracking-note">${icon('shield',15)}${t('trackingSafe')}</small></section><section class="panel tracking-result" aria-live="polite">${tracking===null?`<div class="tracking-placeholder">${laptop()}<h2>${t('trackingEmpty')}</h2><p>${t('trackingHint')}</p></div>`:tracking===false?`<div class="empty"><span>${icon('search',30)}</span><h2>${t('notFound')}</h2></div>`:`<div class="tracking-result-head"><span class="eyebrow">${esc(tracking.id)}</span>${badge(tracking.status)}</div><h2 class="tracked-device">${esc(tracking.device)}</h2><div class="tracking-steps">${STAGES.map((s,i)=>`<div class="tracking-step ${i<=STAGES.indexOf(tracking.status)?'done':''}"><span>${i<STAGES.indexOf(tracking.status)?icon('check',16):'0'+(i+1)}</span><strong>${t(s)}</strong></div>`).join('')}</div><div class="tracking-values"><div><small>${t('estimated')}</small><strong>${date(tracking.deadline)}</strong></div><div><small>${t('trackingCost')}</small><strong>${money(tracking.cost)}</strong></div></div>`}</section></div>`;}
function reportsPage(){const list=filterOrders(state,{from,to}),invalid=from&&to&&from>to;return heading(t('reports'),t('reportIntro'),`<div class="heading-actions">${btn('print-report',t('print'),'printer','secondary')}${btn('csv',t('export'),'download')}</div>`)+`<div class="panel report-toolbar"><span>${t('period')}</span><label>${t('from')}<input id="from-date" type="date" value="${from}" aria-label="${t('from')}"></label><label>${t('to')}<input id="to-date" type="date" value="${to}" aria-label="${t('to')}"></label><button data-action="period" data-days="7">${t('week')}</button><button data-action="period" data-days="30">${t('month')}</button><button data-action="period" data-days="0">${t('allTime')}</button></div>${invalid?`<p class="form-error" role="alert">${t('invalidPeriod')}</p>`:stats(list,true)+`<section class="panel distribution"><div class="section-heading"><h2>${t('distribution')}</h2><span>${list.length} ${t('count')}</span></div><div class="distribution-bar">${STAGES.map(s=>`<span class="${s}" style="flex:${list.filter(o=>o.status===s).length||.015}"></span>`).join('')}</div><div class="distribution-legend">${STAGES.map(s=>`<span>${badge(s)}<b>${list.filter(o=>o.status===s).length}</b></span>`).join('')}</div></section><section class="panel report-table">${table(list)}</section>`}`;}
function renderPage(){return page==='dashboard'?dashboard():page==='orders'?ordersPage():['customers','technicians'].includes(page)?peoplePage(page):page==='portal'?portalPage():reportsPage();}
function updateMain(){const active=document.activeElement,id=active?.id,start=active?.selectionStart,end=active?.selectionEnd;$('#main').innerHTML=renderPage();if(id&&$('#'+id)){const input=$('#'+id);input.focus();if(typeof start==='number'&&input.type!=='date')input.setSelectionRange(start,end);}}
function navigate(next){if(!navItems.some(([p])=>p===next))next='dashboard';page=next;query='';status='';onlyOverdue=false;document.body.classList.remove('menu-open');render();window.scrollTo({top:0,behavior:'instant'});}
function openDialog(content,cls=''){const d=$('#dialog');dialogReturn=document.activeElement;d.className=cls;d.innerHTML=content;if(!d.open)d.showModal();}
function dialogHead(title,sub=''){return `<div class="dialog-head"><div><span class="eyebrow">TEHNOMERKEZ</span><h2 id="dialog-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button type="button" class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div>`;}
function closeDialog(){$('#dialog').close();if(dialogReturn?.isConnected)dialogReturn.focus();}
function field(key,value='',type='text',required=false,extra=''){return `<label>${t(key)}${required?' *':''}<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function orderForm(id){const o=state.orders.find(o=>o.id===id);if(!state.customers.length){openDialog(dialogHead(t('noCustomers'),t('noCustomersHelp'))+`<div class="dialog-actions">${btn('new-customer',t('newCustomer'))}</div>`);return;}
  openDialog(dialogHead(o?`${t('edit')} · ${esc(o.id)}`:t('newOrder'),t('required'))+`<form id="order-form" data-id="${o?.id||''}"><div class="form-grid"><label>${t('customer')} *<select name="customer" required><option value="">${t('chooseCustomer')}</option>${state.customers.map(p=>`<option value="${esc(p.id)}" ${o?.customer===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>${t('technician')}<select name="technician"><option value="">${t('unassigned')}</option>${state.technicians.map(p=>`<option value="${esc(p.id)}" ${o?.technician===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${field('device',o?.device,'text',true,'minlength="2" maxlength="100"')}${field('serial',o?.serial,'text',false,'maxlength="100"')}<label class="full">${t('problem')} *<textarea name="problem" required minlength="3" maxlength="2000" rows="3">${esc(o?.problem)}</textarea></label><label>${t('status')}<select name="status">${STAGES.map(s=>`<option value="${s}" ${(o?.status||'received')===s?'selected':''}>${t(s)}</option>`).join('')}</select></label><label>${t('priority')}<select name="priority"><option value="normal">${t('normal')}</option><option value="urgent" ${o?.priority==='urgent'?'selected':''}>${t('urgent')}</option></select></label>${field('cost',o?.cost??0,'number',true,'min="0" max="1000000" step="0.01"')}${field('deadline',o?.deadline||dayOffset(3),'date',true)}<label class="full">${t('note')}<textarea name="note" maxlength="2000" rows="2" placeholder="${t('noteHelp')}"></textarea></label></div><p class="form-error" id="form-error" role="alert"></p><div class="dialog-actions">${btn('close',t('cancel'),'','secondary','type="button"')}<button class="button primary" type="submit">${icon('check',17)}${t('save')}</button></div></form>`,'wide-dialog');
}
function personForm(kind,id){const p=state[kind].find(p=>p.id===id);openDialog(dialogHead(p?t('personEdit'):t(kind==='customers'?'newCustomer':'newTechnician'))+`<form id="person-form" data-kind="${kind}" data-id="${p?.id||''}"><div class="form-grid">${field('name',p?.name,'text',true,'minlength="2" maxlength="100"')}${field('phone',p?.phone,'tel',true,'minlength="5" maxlength="30"')}${kind==='customers'?field('email',p?.email,'email',false,'maxlength="100"'):field('specialty',p?.specialty,'text',false,'maxlength="100"')}</div><p class="form-error" id="form-error" role="alert"></p><div class="dialog-actions">${btn('close',t('cancel'),'','secondary','type="button"')}<button class="button primary" type="submit">${t('save')}${icon('check',17)}</button></div></form>`);}
function details(id){const o=state.orders.find(o=>o.id===id);if(!o)return;openDialog(dialogHead(esc(o.device),`${esc(o.id)} · ${t('created')} ${date(o.created)}`)+`<div class="detail-status">${badge(o.status)}<span class="${o.priority==='urgent'?'urgent-text':''}">${t(o.priority)}</span></div><div class="detail-grid">${[['customer',person(o.customer)?.name],['phone',person(o.customer)?.phone],['technician',person(o.technician,'technicians')?.name||t('unassigned')],['deadline',date(o.deadline)],['serial',o.serial||'—'],['cost',money(o.cost)]].map(([k,v])=>`<div><small>${t(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="problem-box"><small>${t('problem')}</small><p>${esc(o.problem)}</p></div><div class="code-box"><div><small>${t('trackingCode')}</small><code>${esc(o.token)}</code></div><button class="icon-button" data-action="copy" data-id="${esc(o.id)}" aria-label="${t('copyCode')}">${icon('copy',19)}</button></div><h3 class="history-title">${t('history')}</h3><div class="history">${o.history.slice().reverse().map(h=>`<div><i class="status-dot ${h.status}"></i><div><strong>${t(h.status)}</strong><small>${fullDate(h.date)} · ${money(h.cost)}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</div></div>`).join('')}</div><div class="detail-actions">${btn('print-order',t('receipt'),'printer','secondary',`data-id="${o.id}"`)}${btn('edit-order',t('edit'),'wrench','secondary',`data-id="${o.id}"`)}${o.status!=='completed'?btn('advance',t(STAGES[STAGES.indexOf(o.status)+1]),'arrow','primary',`data-id="${o.id}"`):`<span class="completed-label">${icon('check',18)}${t('finished')}</span>`}</div>`,'wide-dialog');}
function advanceForm(id){const o=state.orders.find(o=>o.id===id);if(!o||o.status==='completed')return;const next=STAGES[STAGES.indexOf(o.status)+1];openDialog(dialogHead(t('statusUpdate'),esc(o.id)+' · '+esc(o.device))+`<div class="stage-transition">${badge(o.status)}${icon('arrow',18)}${badge(next)}</div><form id="advance-form" data-id="${esc(id)}"><label>${t('note')}<textarea name="note" maxlength="2000" rows="3" placeholder="${t('noteHelp')}"></textarea></label><div class="dialog-actions">${btn('detail',t('cancel'),'','secondary',`type="button" data-id="${id}"`)}<button class="button primary" type="submit">${t('save')}${icon('check',17)}</button></div></form>`);}
function settings(){openDialog(dialogHead(t('settings'),t('settingsHelp'))+`<div class="settings-note">${icon('info',20)}<p>${t('localNote')}</p></div><div class="settings-actions">${btn('backup',t('backup'),'download','secondary')}${btn('restore',t('restore'),'upload','secondary')}</div>`);}
function notifications(){const orders=state.orders.filter(o=>isOverdue(o)||o.status==='ready');openDialog(dialogHead(t('notification'),t('notificationsTitle'))+`<div class="notification-list">${orders.map(o=>`<button data-action="detail" data-id="${o.id}"><span class="notification-icon ${isOverdue(o)?'late':''}">${icon(isOverdue(o)?'clock':'check',20)}</span><span><strong>${esc(o.device)}</strong><small>${o.id} · ${t(isOverdue(o)?'overdue':'readyAlert')}</small></span>${icon('chevron',16)}</button>`).join('')||`<p>${t('noAlerts')}</p>`}</div>`);}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('downloaded'));}
function exportCSV(){if(from&&to&&from>to){toast(t('invalidPeriod'));return;}const headers=['orderId','device','customer','status','technician','cost','deadline','created'];const rows=filterOrders(state,{from,to}).map(o=>[o.id,o.device,person(o.customer)?.name,t(o.status),person(o.technician,'technicians')?.name||t('unassigned'),o.cost,o.deadline,o.created.slice(0,10)]);download('\ufeff'+[headers.map(t),...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'TehnoMerkez-'+localDay()+'.csv','text/csv;charset=utf-8');}
function printOrder(id){const o=state.orders.find(o=>o.id===id);$('#print-area').innerHTML=`<h1>TehnoMerkez</h1><p>${t('receipt')} · ${o.id}</p><h2>${esc(o.device)}</h2><dl>${[['customer',person(o.customer)?.name],['phone',person(o.customer)?.phone],['serial',o.serial],['problem',o.problem],['status',t(o.status)],['deadline',o.deadline],['cost',money(o.cost)],['trackingCode',o.token]].map(([k,v])=>`<dt>${t(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p>${t('printNote')}</p>`;document.body.classList.add('printing');window.print();}
function printReport(){if(from&&to&&from>to){toast(t('invalidPeriod'));return;}const list=filterOrders(state,{from,to});$('#print-area').innerHTML=`<h1>TehnoMerkez</h1><h2>${t('report')}</h2><p>${from||'—'} → ${to||'—'}</p><p>${t('reportCount')}: ${list.length} · ${t('total')}: ${money(summary(list).total)}</p><table><thead><tr>${['orderId','device','status','cost','deadline'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${list.map(o=>`<tr><td>${o.id}</td><td>${esc(o.device)}</td><td>${t(o.status)}</td><td>${money(o.cost)}</td><td>${o.deadline}</td></tr>`).join('')}</tbody></table><p>${t('localNote')}</p>`;document.body.classList.add('printing');window.print();}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  if(a==='new-order')orderForm();else if(a==='new-customer')personForm('customers');else if(a==='new-technician')personForm('technicians');else if(a==='edit-person')personForm(b.dataset.kind,id);else if(a==='detail')details(id);else if(a==='edit-order')orderForm(id);else if(a==='advance')advanceForm(id);else if(a==='close')closeDialog();else if(a==='settings')settings();else if(a==='notifications')notifications();else if(a==='menu')document.body.classList.toggle('menu-open');else if(a==='close-menu')document.body.classList.remove('menu-open');else if(a==='clear'){query='';status='';onlyOverdue=false;updateMain();}else if(a==='stage-filter'||a==='overdue'){page='orders';query='';status=b.dataset.status||'';onlyOverdue=a==='overdue';history.replaceState(null,'','#orders');render();}else if(a==='period'){from=+b.dataset.days?dayOffset(1-Number(b.dataset.days)):'';to=+b.dataset.days?localDay():'';updateMain();}else if(a==='copy'){const o=state.orders.find(o=>o.id===id);try{await navigator.clipboard.writeText(`${o.id}\n${o.token}`);toast(t('copied'));}catch{toast(t('copyFailed'));}}else if(a==='csv')exportCSV();else if(a==='backup')download(JSON.stringify(state,null,2),'TehnoMerkez-backup-'+localDay()+'.json','application/json');else if(a==='print-order')printOrder(id);else if(a==='print-report')printReport();else if(a==='restore'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>5_000_000)throw Error();const parsed=JSON.parse(await file.text());if(!validState(parsed))throw Error();pendingImport=parsed;openDialog(dialogHead(t('restoreTitle'),t('restoreHelp'))+`<div class="dialog-actions">${btn('close',t('cancel'),'','secondary')}${btn('confirm-restore',t('restoreConfirm'),'upload')}</div>`);}catch{toast(t('invalidBackup'));}};input.click();}else if(a==='confirm-restore'&&pendingImport){const ok=persist(pendingImport);pendingImport=null;tracking=null;closeDialog();render();if(ok)toast(t('restoreDone'));}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateMain();}});
document.addEventListener('change',e=>{if(e.target.id==='language'){lang=e.target.value;try{localStorage.setItem('tm-demo-language',lang);}catch{}render();}else if(e.target.id==='status-filter'){status=e.target.value;updateMain();}else if(e.target.id==='from-date'||e.target.id==='to-date'){if(e.target.id==='from-date')from=e.target.value;else to=e.target.value;updateMain();}});
document.addEventListener('submit',e=>{
  const f=e.target,formId=f.getAttribute('id');if(!['order-form','person-form','advance-form','tracking-form'].includes(formId))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));
  if(formId==='tracking-form'){trackingInput=data;tracking=trackOrder(state,data.id,data.token)||false;updateMain();return;}
  try{let next,id=f.dataset.id;
    if(formId==='order-form'){data.cost=Number(data.cost);next=saveOrder(state,data,id||undefined);id=id||next.orders[0].id;}
    else if(formId==='advance-form'){const o=state.orders.find(o=>o.id===id);next=saveOrder(state,{...o,status:STAGES[STAGES.indexOf(o.status)+1],note:data.note},id);}
    else {if(data.name.trim().length<2||data.phone.trim().length<5)throw Error('invalidPerson');const kind=f.dataset.kind;const record={...data,name:data.name.trim(),phone:data.phone.trim(),id:id||crypto.randomUUID()};next={...state,[kind]:id?state[kind].map(p=>p.id===id?record:p):[...state[kind],record]};}
    const ok=persist(next);closeDialog();render();if(formId==='order-form'||formId==='advance-form')details(id);if(ok)toast(t('saved'));
  }catch(err){const el=$('#form-error');if(el)el.textContent=t(err.message);else toast(t(err.message));}
});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
navigate(location.hash.slice(1)||'dashboard');
if(loadMessage)toast(t(loadMessage));
